import{_ as o,o as t,c as d,a4 as c}from"./chunks/framework.WdFb_vN1.js";const u=JSON.parse('{"title":"Stable API (v1)","description":"","frontmatter":{},"headers":[],"relativePath":"map/core/stable-api.md","filePath":"map/core/stable-api.md","lastUpdated":1790097597000}'),r={name:"map/core/stable-api.md"};function a(s,e,n,i,l,p){return t(),d("div",null,e[0]||(e[0]=[c('<h1 id="stable-api-v1" tabindex="-1">Stable API (v1) <a class="header-anchor" href="#stable-api-v1" aria-label="Permalink to &quot;Stable API (v1)&quot;">​</a></h1><p>Allowlist of symbols and protocols we treat as <strong>Stable</strong> for SemVer on <code>1.x</code>.</p><p>Root and domain barrels use <strong>explicit named exports</strong> (no public <code>export *</code>). Root <code>src/index.ts</code> imports leaves directly (no <code>internal-barrel</code>). Runtime surface is locked by <code>public-api.spec.ts</code> (root <strong>and</strong> each domain subpath).</p><p><strong>All current root and subpath runtime exports are Stable or Experimental.</strong> For Vue/React <code>map-core</code>, Experimental field/UI helpers live on <strong><code>./fields</code></strong> (not the root). Other packages may list Experimental symbols in <code>*_EXPERIMENTAL_RUNTIME_EXPORTS</code> on a published barrel (may change in a <strong>minor</strong>). Removing an Experimental export from a published barrel is still a <strong>major</strong>.</p><p><strong>Runtime lock:</strong> each entry asserts <code>Object.keys(import * as api from &#39;&lt;entry&gt;&#39;)</code> equals its Stable ∪ Experimental allowlist in <code>public-api.spec.ts</code> (type-only exports are erased at runtime and omitted from the lock). Root and subpaths may export <strong>first-party</strong> types via explicit <code>export type { … }</code> — do <strong>not</strong> re-export types that already live in third-party packages (<code>geojson</code>, <code>maplibre-gl</code>, …); import those from the original package.</p><table tabindex="0"><thead><tr><th>Package</th><th>Spec</th></tr></thead><tbody><tr><td><code>@hungpvq/map-core</code></td><td><code>libs/map-core/core/src/public-api.spec.ts</code> (root + subpaths)</td></tr><tr><td><code>@hungpvq/map-dataset</code></td><td><code>libs/map-core/map-dataset/src/public-api.spec.ts</code></td></tr><tr><td><code>@hungpvq/map-draw</code></td><td><code>libs/map-core/map-draw/src/public-api.spec.ts</code></td></tr><tr><td><code>@hungpvq/vue-map-core</code></td><td><code>libs/vue/map-core/src/public-api.spec.ts</code></td></tr><tr><td><code>@hungpvq/vue-map-dataset</code></td><td><code>libs/vue/map-dataset/src/public-api.spec.ts</code></td></tr><tr><td><code>@hungpvq/vue-map-draw</code></td><td><code>libs/vue/map-draw/src/public-api.spec.ts</code></td></tr><tr><td><code>@hungpvq/vue-map-devtools</code></td><td><code>libs/vue/map-devtools/src/public-api.spec.ts</code></td></tr><tr><td><code>@hungpvq/react-map-core</code></td><td><code>libs/react/map-core/src/public-api.spec.ts</code></td></tr><tr><td><code>@hungpvq/react-map-dataset</code></td><td><code>libs/react/map-dataset/src/public-api.spec.ts</code></td></tr><tr><td><code>@hungpvq/react-map-draw</code></td><td><code>libs/react/map-draw/src/public-api.spec.ts</code></td></tr><tr><td><code>@hungpvq/react-map-devtools</code></td><td><code>libs/react/map-devtools/src/public-api.spec.ts</code></td></tr></tbody></table><ul><li>Adding a <strong>runtime</strong> export → named export in the entry barrel + Stable (or Experimental) list in that package’s <code>public-api.spec.ts</code> + this page when documenting the area.</li><li>Removing a root <strong>or</strong> subpath runtime export is a <strong>major</strong>. Adding a <strong>new</strong> subpath while keeping root is usually a <strong>minor</strong>.</li></ul><h3 id="canonical-imports" tabindex="-1">Canonical imports <a class="header-anchor" href="#canonical-imports" aria-label="Permalink to &quot;Canonical imports&quot;">​</a></h3><p>Prefer <strong>domain subpaths</strong> for feature APIs; use the root barrel for platform/runtime symbols (<code>getMap</code>, <code>MapStoreManager</code>, <code>UniversalRegistry</code>, …):</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { getMap, subscribeMapReady } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;@hungpvq/map-core&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { createMeasurementSession } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;@hungpvq/map-core/measurement&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { createIdentifySession } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;@hungpvq/map-dataset/identify&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { createDrawSession } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;@hungpvq/map-draw&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>Adapters (<code>@hungpvq/vue-*</code> / <code>@hungpvq/react-*</code>) must <strong>not</strong> re-export core protocol — import UI from adapters, protocol from core/dataset/draw.</p><h3 id="export-removal-checklist-do-not-skip" tabindex="-1">Export removal checklist (do not skip) <a class="header-anchor" href="#export-removal-checklist-do-not-skip" aria-label="Permalink to &quot;Export removal checklist (do not skip)&quot;">​</a></h3><p>Before removing a published runtime export (Stable <strong>or</strong> Experimental on a barrel):</p><ol><li>Classify Stable vs Experimental; confirm it is not a control/menu id, store key, CSS token, or protocol string.</li><li>Grep first-party map packages, demos, and docs. Tag: <code>in-use-first-party</code> | <code>docs-only</code> | <code>looks-unused-internal</code> | <code>unknown-external</code>.</li><li><strong>SemVer major</strong> for any remove from a published barrel (Experimental included).</li><li>Update <strong>together</strong>: barrel <code>index.ts</code>, <code>*_STABLE_*</code> / <code>*_EXPERIMENTAL_*</code> in <code>public-api.spec.ts</code>, this page.</li><li>Prefer <code>@deprecated</code> alias for ≥1 minor when <code>unknown-external</code> or docs still reference the symbol.</li><li><strong>Forbidden:</strong> delete an export only because “no monorepo import” without steps 3–4.</li></ol><h3 id="export-inventory-hardening-pass" tabindex="-1">Export inventory (hardening pass) <a class="header-anchor" href="#export-inventory-hardening-pass" aria-label="Permalink to &quot;Export inventory (hardening pass)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Symbol</th><th>Package</th><th>Tag</th><th>Action</th></tr></thead><tbody><tr><td><code>logger</code> (root)</td><td><code>@hungpvq/map-draw</code></td><td>in-use-first-party (vue/react map-draw stores)</td><td><strong>Keep</strong> Experimental</td></tr><tr><td><code>brightColor</code>, <code>generateInspectStyle</code>, <code>renderPopup</code>, …</td><td><code>@hungpvq/map-draw</code></td><td>in-use-first-party</td><td>Keep (InspectControl)</td></tr><tr><td><code>emptyDraftListSnapshot</code></td><td><code>@hungpvq/map-draw</code></td><td>in-use-first-party</td><td>Keep (useDrawDrafts)</td></tr><tr><td><code>cycleMapThemeMode</code></td><td><code>@hungpvq/map-core/theme</code></td><td>in-use-first-party / docs</td><td>Keep</td></tr><tr><td>Inspect GIS helpers (<code>getSourcesFromMap</code>, …)</td><td><code>@hungpvq/map-draw</code></td><td>unknown-external</td><td>Keep (public Inspect extension surface)</td></tr></tbody></table><p>Related: <a href="https://github.com/hung4564/vue-library/blob/main/libs/map-core/README.md#checklist-semver--breaking-change" target="_blank" rel="noreferrer">SemVer checklist</a> · <a href="./minimal-starter.html">Minimal starter</a> · <a href="./peers-and-bundle.html">Peers and bundle</a> · <a href="./map-store.html">Map store</a> · <a href="./error-handling.html">Error handling</a> · <a href="./registry-controls.html">UniversalRegistry controls</a> · <a href="./registry-components.html">components</a></p><h2 id="maplibre-first" tabindex="-1">MapLibre-first <a class="header-anchor" href="#maplibre-first" aria-label="Permalink to &quot;MapLibre-first&quot;">​</a></h2><p><code>MapSimple</code> is the Stable MapLibre map type. Platform APIs (<code>getMap</code>, <code>subscribeMapReady</code>, control helpers) take or return that instance — we do <strong>not</strong> hide MapLibre behind a custom engine facade. Apps may call MapLibre APIs on the instance directly.</p><h2 id="thin-host-controls" tabindex="-1">Thin-host controls <a class="header-anchor" href="#thin-host-controls" aria-label="Permalink to &quot;Thin-host controls&quot;">​</a></h2><p>Dual Vue/React controls share <strong>pure orchestration</strong> in <code>@hungpvq/map-core</code> (root <code>controls/*</code> or domain subpaths), <code>@hungpvq/map-dataset</code>, or <code>@hungpvq/map-draw</code>. Adapters stay thin hosts (<code>useMap</code> + register/toolbar + SFC/JSX). Prefer <code>subscribeMapReady</code> when waiting for the map with cancel-on-unmount. Do not merge adapter packages or put framework UI into core.</p><p>Pure owners to copy (non-exhaustive):</p><table tabindex="0"><thead><tr><th>Area</th><th>Core helper</th></tr></thead><tbody><tr><td>Shell controls</td><td>root <code>controls/*</code> (<code>captureHomeView</code>, <code>goHome</code>, navigation / globe / goto / setting / mouse-coordinates / info)</td></tr><tr><td>Identify session</td><td><code>createIdentifySession</code> / <code>createIdentifyControlModel</code> (<code>@hungpvq/map-dataset/identify</code>) — session owns <code>runIdentifyMulti</code> + input modes; adapters are thin hosts</td></tr><tr><td>Measurement</td><td><code>createMeasurementSession</code> / <code>createMeasurementMapView*</code> (<code>./measurement</code>)</td></tr><tr><td>Print advanced</td><td><code>createPrintAdvancedSession</code> (<code>./print</code>)</td></tr><tr><td>Toolbar / CRS</td><td><code>createLiveToolbarStrategy</code> (<code>./toolbar</code>), <code>normalizeDisplayEpsgs</code> (<code>./crs</code>)</td></tr><tr><td>Draw / inspect</td><td><code>createDrawSession</code>, <code>draw-control-helpers</code>, <code>InspectController</code> (<code>@hungpvq/map-draw</code>)</td></tr><tr><td>Misc</td><td><code>GeoLocateSession</code>, <code>createCopyFeedback</code>, theme / fullscreen helpers</td></tr></tbody></table><p>Hosts own UI, registry actions, and framework lifecycle only.</p><h2 id="registry-architecture" tabindex="-1">Registry architecture <a class="header-anchor" href="#registry-architecture" aria-label="Permalink to &quot;Registry architecture&quot;">​</a></h2><ul><li><strong>Host:</strong> <code>UniversalRegistry</code> in <code>@hungpvq/map-core</code> — methods, menu handlers, components, control handles (one resolve path: map-scoped then global). Storage: <code>@hungpvq/shared-store</code> keys <code>map:registry:global</code> / <code>map:registry:maps</code> / <code>map:registry:controls</code> (no class-static <code>Map</code> singletons).</li><li><strong>Adapters:</strong> <code>@hungpvq/vue-map-core</code> / <code>@hungpvq/react-map-core</code> <strong>extend</strong> that class and only add typed <code>registerComponent</code> / <code>getComponent</code> (Vue also <code>markRaw</code>).</li><li>Prefer <code>UniversalRegistry</code> / <code>runMapControlAction</code> from <code>@hungpvq/map-core</code> in framework-agnostic code (<code>map-dataset</code>, context menu).</li></ul><h2 id="hungpvq-map-core-package-entries" tabindex="-1"><code>@hungpvq/map-core</code> package entries <a class="header-anchor" href="#hungpvq-map-core-package-entries" aria-label="Permalink to &quot;`@hungpvq/map-core` package entries&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Entry</th><th>Role</th></tr></thead><tbody><tr><td><code>.</code></td><td>Platform shell: store/<code>getMap</code>/<code>subscribeMapReady</code>, registry, errors, mitt, shared GIS utils, shell locales, host <code>WorkerMonitor</code>, thin-host control helpers (<code>captureHomeView</code>, <code>goHome</code>, navigation/globe/goto/setting/mouse-coordinates/info)</td></tr><tr><td><code>./style.css</code></td><td>Shared map CSS</td></tr><tr><td><code>./assets/*</code></td><td>Static assets (basemap thumbnails under <code>assets/basemap/</code>)</td></tr><tr><td><code>./worker</code></td><td>CSS/DOM-free worker helpers</td></tr><tr><td><code>./basemap</code></td><td>Basemap adapters, services, <code>INIT_BASEMAPS</code>, <code>createDefaultBaseMapStore</code>, <code>BasemapManager</code> / <code>getOrCreateBasemapManager</code> (on <code>MAP_STORE_KEY.BASEMAP</code>), <code>validateBasemapSource</code> / <code>createCustomBasemapItem</code> / <code>isCustomBasemapItem</code>, <code>getBasemapOpacityPaintKeys</code>, <code>BasemapError</code>, domain <code>logger</code> (<code>map:basemap</code>)</td></tr><tr><td><code>./crs</code></td><td>CRS catalog, store defaults, <code>CRS_CONTROL_LOCALE</code>, <code>createCoordinateFormatter</code>, <code>normalizeDisplayEpsgs</code>, domain <code>logger</code> (<code>map:crs</code>)</td></tr><tr><td><code>./devtools</code></td><td>Devtools store core: <code>getMapDebugStore</code> / <code>configureDevtoolLogStore</code> / <code>createDevtoolLogAdapter</code> / <code>getDevtoolLogDataStore</code> / <code>refreshDevtoolLogsFromStore</code> / <code>clearDevtoolLogsForMapId</code> / <code>clearDevtoolErrorsForMapId</code> (default uncapped IndexedDB; custom <code>LogDataStore</code> allowed; <code>removeMap</code> clears that map’s logs/errors), <code>installDevtoolsCore</code> (Experimental)</td></tr><tr><td><code>./event</code></td><td><code>EventManager</code>, event models, bbox ranger, <code>createEventActionSync</code>, <code>groupEventsByMapType</code> / <code>isEventActive</code>, domain <code>logger</code> (<code>map:event</code>)</td></tr><tr><td><code>./image</code></td><td>Map image load/store helpers, domain <code>logger</code> (<code>map:image</code>)</td></tr><tr><td><code>./legend</code></td><td><code>LegendService</code>, <code>MapLegend</code>, <code>buildLayerLegendElements</code>, paint helpers</td></tr><tr><td><code>./measurement</code></td><td><code>MeasurementService</code>, measure modes, format helpers, <code>resolveMeasurementModeToggle</code> / <code>resolveMeasurementToolbarStatus</code>, <code>createMeasurementSession</code>, <code>createMeasurementMapView</code> / <code>createMeasurementMapViewLayers</code>, <code>draftCoordinatesToFeature</code> / <code>buildMeasurementGeojsonDownload</code>, domain <code>logger</code> (<code>map:measurement</code>)</td></tr><tr><td><code>./menu</code></td><td>Map context menu builders / actions</td></tr><tr><td><code>./print</code></td><td><code>PrintService</code>, export helpers (<code>exportMapbox*</code>, <code>printMapToFile</code>, <code>clipCanvasRegion</code>, <code>waitMapIdleAndTiles</code>), <code>createPrintAdvancedSession</code> / <code>DEFAULT_PRINT_ADVANCED_SETTING</code>, domain <code>logger</code> (<code>map:print</code>)</td></tr><tr><td><code>./theme</code></td><td>Theme bootstrap / resolve / <code>MAP_THEME_*</code>, <code>MAP_THEME_CONTRAST_CLASS</code>, <code>subscribePrefersContrastMore</code>; optional per-map helpers <code>resolveMapThemeElement</code> / <code>applyMapThemeClassToElement</code> / <code>applyMapThemeForMap</code> (document theme remains default)</td></tr><tr><td><code>./toolbar</code></td><td>Toolbar strategies / store APIs, <code>createLiveToolbarStrategy</code>, domain <code>logger</code> (<code>map:toolbar</code>)</td></tr></tbody></table><h3 id="root-highlights" tabindex="-1">Root (<code>.</code>) highlights <a class="header-anchor" href="#root-highlights" aria-label="Permalink to &quot;Root (`.`) highlights&quot;">​</a></h3><p>Runtime allowlist: <code>MAP_CORE_STABLE_RUNTIME_EXPORTS</code> in <code>public-api.spec.ts</code> (~80 symbols).</p><table tabindex="0"><thead><tr><th>Area</th><th>Stable surface</th></tr></thead><tbody><tr><td>Map access</td><td><code>getMap</code> → <code>MapSimple | undefined</code>, <code>subscribeMapReady</code> → unsubscribe, <code>registerMapAccessor</code> (+ <code>{ hostId }</code>, returns unregister), <code>registerMapReadySubscriber</code>, <code>registerMapStoreCleanup</code>, <code>MAP_PLATFORM_HOST</code>, <code>listMapPlatformHosts</code>, <code>MAP_PLATFORM_REGISTRY_METHOD</code> (reserved UniversalRegistry global keys), <code>MapStoreManager</code>, <code>MAP_STORE_KEY</code>, <code>hasMapInstance</code>, <code>registerMapDomainStoreFactory</code> / <code>ensureMapDomainStore</code> / <code>hasMapDomainStoreFactory</code> (domain bags on <code>map:core[mapId]</code>; not <code>meta.registries</code>), <code>ensureMapMitt</code> / <code>ensureMapLangStore</code> / <code>ensureMapLocaleApi</code> — <a href="./map-store.html">map-store</a>. Domain subpaths also export <code>ensureMap*Store</code> / <code>ensureMap*Api</code> (event, image, toolbar, crs, print, basemap). <strong>Theme bootstrap is process-global</strong> (one <code>html</code> theme); platform accessors are <strong>multi-host</strong>.</td></tr><tr><td>Thin-host control helpers</td><td>Home (<code>captureHomeView</code> / <code>goHome</code>), navigation (<code>zoomIn</code> / <code>zoomOut</code> / <code>resetBearing</code> / <code>attachRotateListener</code> / …), globe (<code>toggleGlobeProjection</code> / …), goto / setting / mouse-coordinates / info attach helpers</td></tr><tr><td>Registry</td><td><code>UniversalRegistry</code>, <code>runMapControlAction</code>, <code>buildMapControlHandle</code>, <code>MapControlHandle</code>, <code>REGISTRY_*</code> (incl. <code>REGISTRY_GLOBAL_STORE_KEY</code> / <code>REGISTRY_MAPS_STORE_KEY</code> / <code>REGISTRY_CONTROLS_STORE_KEY</code>), <code>filterMapControls</code> (<code>RegistryFn</code> = <code>(...args: unknown[]) =&gt; unknown</code>) — backed by <code>@hungpvq/shared-store</code></td></tr><tr><td>Init / errors</td><td><code>MapInitializer</code>, <code>MapError</code> family, <code>errorHandler</code> / <code>MapErrorHandler</code> — <a href="./error-handling.html">error-handling</a></td></tr><tr><td>A11y</td><td><code>bindMapKeyboardShortcuts</code>, <code>closeTopOpenMapControl</code>, <code>focusMapLayerSearch</code>, <code>MAP_LAYER_SEARCH_SELECTOR</code>, <code>mapLayerSearchSelector</code></td></tr><tr><td>Shared GIS</td><td><code>fitBounds</code> (sidebar left/right padding), <code>bboxFromGeojson</code>, <code>isValidBbox</code>, <code>reprojectGeojson</code>, <code>reprojectGeojsonToWgs84</code>, coordinate/DMS helpers (<code>parseCoordinateText</code>, <code>latDMS</code>/<code>lngDMS</code>), color (<code>getChartRandomColor</code>, <code>getChartColorAt</code>) / <code>logHelper</code>, map-info (<code>copyImageDataUrl</code>)</td></tr><tr><td>Pointer / touch</td><td><code>getMapPointerProfile</code>, <code>bindMapLongPress</code></td></tr><tr><td>Fullscreen</td><td><code>requestElementFullscreen</code>, <code>exitDocumentFullscreen</code>, <code>toggleElementFullscreen</code>, <code>subscribeFullscreenChange</code>, <code>getFullscreenElement</code>, <code>isDocumentFullscreen</code>, <code>isMapRootFullscreen</code>, <code>resolveMapFullscreenTarget</code></td></tr><tr><td>Control layout</td><td><code>resolveControlLayout</code>, <code>ResolvedControlLayout</code> (<code>standalone</code> / <code>toolbar</code> / <code>menu</code>), <code>ControlLayout</code> (<code>standalone</code> / <code>toolbar</code> / <code>button</code>), <code>ButtonInMobile</code> / <code>BUTTON_IN_MOBILE_VALUES</code> (<code>button</code> / <code>toolbar</code> / <code>menu</code>). Map <code>buttonInMobile</code> on viewports ≤640px: <code>button</code> leaves corner controls unchanged; <code>toolbar</code> promotes into one <code>ToolbarControl</code> host except <code>controlLayout=&quot;button&quot;</code>; <code>menu</code> fans out by <code>position</code> into corner stacks with outside-in overflow; bottom half budgets menu + same-edge <code>controlLayout=&quot;button&quot;</code> chrome (see <a href="./module/ToolbarControl.html">ToolbarControl</a>). Mount <code>ToolbarControl</code> in the map slot for <code>toolbar</code> and <code>menu</code>.</td></tr><tr><td>Button chrome helpers</td><td><code>MAP_BUTTON_VARIANTS</code> / <code>MAP_BUTTON_SIZES</code> / <code>MAP_BUTTON_SIZE_PX</code>, <code>resolveMapButtonSizePx</code>, <code>mapButtonVariantClass</code>, <code>mapButtonSizeClass</code>, … (used by Vue/React <code>MapControlButton</code>)</td></tr><tr><td>ModuleContainer helpers</td><td><code>moduleCornerHostSelector</code> / <code>moduleDraggableHostSelector</code> (+ id variants), <code>buildModuleBindPosition</code>, <code>moduleBtnContainerClassName</code>, <code>isModuleCornerChromeVisible</code>, <code>queryModuleHostElement</code> (Vue/React <code>ModuleContainer</code>)</td></tr><tr><td>Worker host</td><td><code>WorkerMonitor</code> (+ <code>abortTask</code>), <code>connectWorkerMonitor</code>, <code>abortWorkerMonitorTask</code>, <code>createWorkerMonitorAbortMessage</code>, <code>runMonitoredTask</code>, <code>workerHasHistory</code> / <code>anyWorkerHasHistory</code> / <code>countBusyWorkers</code>, <code>createWorkerUiDelayState</code> (WorkerControl busy/loading anti-flicker), … (in-worker: <code>./worker</code>)</td></tr><tr><td>Shell locales</td><td><code>MAP_ACTION_*</code>, Home/Goto/Globe/Info/Setting, <code>WORKER_*</code>, <code>REGISTRY_*</code>, <code>LANGUAGE_*</code>, <code>MAP_CORE_LOCALE_EN</code>, <code>MAP_CORE_LOCALE_VI</code>, <code>registerMapCoreBuiltinLocales</code></td></tr><tr><td>Lang API</td><td><code>registerLocale</code> / <code>registerLocaleFlat</code> / <code>setLanguage</code> / <code>loadLocale</code> / <code>MAP_BUILTIN_LANGUAGES</code> / flat helpers (via <code>createMapLocaleApi</code> + root exports); domain logger <code>mapLangLogger</code> (<code>map:lang</code>); built-in packs auto-register on first <code>ensureMapLocaleApi</code></td></tr><tr><td>Types</td><td><code>MapSimple</code>, <code>WithMapPropType</code>, <code>ControlLayout</code>, <code>MapControlHandle</code>, …</td></tr></tbody></table><p>Domain APIs (<strong>theme, basemap, measurement, …</strong>) are <strong>not</strong> on the root barrel — import from the matching subpath.</p><p>Toolbar helpers on <code>@hungpvq/map-core/toolbar</code>: <code>mdiIcon</code>, <code>mdiButtonState</code>, <code>compassIcon</code>, <code>createLiveToolbarStrategy</code>; overflow helpers <code>groupToolbarButtons</code>, <code>splitToolbarOverflow</code>, <code>splitToolbarOverflowKeepGroups</code> (<code>prefer</code> <code>&#39;start&#39;</code>|<code>&#39;end&#39;</code>, <code>toolbarGroupHeightCost</code>), <code>maxVisibleToolbarButtons</code>, <code>maxVisibleButtonsInStackHeight</code>, <code>cornerVerticalMenuBudgetsPx</code>, <code>measureCornerStandaloneReserved</code>, <code>measureCornerMenuUsedPx</code>, <code>elementOuterSize</code>, <code>toolbarAvailableWidth</code>, <code>toolbarGroupHeightCost</code>, <code>toolbarOverflowPanelClassName</code>, <code>planToolbarLayout</code>, <code>TOOLBAR_EDGE_INSET_PX</code>, <code>TOOLBAR_STACK_GAP_PX</code>, <code>BUTTON_GROUP_OVERFLOW_FRACTION</code>, <code>TOOLBAR_CONTROL_LOCALE</code>.</p><h2 id="hungpvq-map-dataset" tabindex="-1"><code>@hungpvq/map-dataset</code> <a class="header-anchor" href="#hungpvq-map-dataset" aria-label="Permalink to &quot;`@hungpvq/map-dataset`&quot;">​</a></h2><p><strong>Breaking major:</strong> domain symbols moved off the root onto named subpaths. Root no longer re-exports builders, identify, menu, style, create-control, geo-export, or attribute-table APIs. Full runtime allowlists: <code>public-api.spec.ts</code> (root + each subpath).</p><table tabindex="0"><thead><tr><th>Entry</th><th>Stable surface (highlights)</th></tr></thead><tbody><tr><td><code>.</code></td><td><code>DatasetService</code>, <code>MAP_DATASET_STORE_KEY</code> / <code>ensureMapDatasetStore</code> / <code>createDefaultMapDatasetStore</code> / <code>notifyMapDatasetStore</code> (domain bag on <code>map:core[mapId]</code>), tree/<code>createRootDataset</code>/<code>createGroupDataset</code>, <code>convertListToTree</code> / <code>convertTreeToList</code> / <code>mergeEmptyGroups</code> / <code>createDefaultGroup</code> / <code>isGroupNode</code>, layer-list types (<code>LayerListItem</code> / <code>LayerListTreeNode</code> / <code>LayerListGroupTree</code> / <code>ListViewGroupRef</code> / <code>IListViewUI</code> / <code>IGroupListViewUI</code>), <code>getLayerControlTitleMenuState</code> / <code>registerAddGeojsonHereForMap</code>, generic parts, layer/dataset locales, <code>createDataManagement</code> / <code>isDataManagementView</code>, <code>warnIfDatasetRegistryMissing</code> / <code>resetDatasetRegistryWarnFlag</code>, <code>IDataset</code> (+ shared protocol types). Experimental: <code>upsertDatasetComponent</code> / <code>removeDatasetComponent</code>, <code>logger</code> / <code>loggerIdentify</code> / <code>loggerHighlight</code></td></tr><tr><td><code>./highlight</code></td><td><code>createHighlightPart</code>, <code>getHighlightController</code> / <code>destroyHighlightController</code> / <code>bindHighlightPickDatasets</code>, dataset UI mitt (<code>MAP_DATASET_EVENT</code>, <code>MapDatasetClosePayload</code> <code>{ mapId, item?, dataset? }</code>, <code>MapDatasetClearPayload</code> <code>{ mapId, target, dataset? }</code>, <code>bindHighlightMittBridge</code> / <code>releaseHighlightMittBridge</code> / <code>cleanHighlightMittBridge</code>·<code>destroyHighlightMittBridge</code>, <code>emitHighlight*</code>), cascade defaults (<code>DEFAULT_HIGHLIGHT_*</code>); types <code>HighlightPartOptions</code>, <code>HighlightController</code>, <code>IHighlightPart</code>, <code>MapDatasetEvent</code>, … (cascade/query/resolve + paint-layer helpers are package-internal)</td></tr><tr><td><code>./attribute-table</code></td><td><code>ATTRIBUTE_TABLE_*</code>, <code>createAttributeTableController</code> / stores (+ optional <code>invalidate</code>), <code>createDatasetPartAttributeTable</code> (<code>columns</code> / <code>ui</code>), <code>createMenuItemAttributeTable</code>, column/sort helpers, <code>resolveAttributeTable*Option</code>, <code>AttributeTableProps</code> / view / toolbar / pager / grid props</td></tr><tr><td><code>./geojson</code></td><td><code>createGeoJsonDataset</code>, <code>createGeojsonHereDataset</code>, <code>ensureGeojsonFeatureIds</code> / <code>GEOJSON_FEATURE_ID_KEY</code> (auto <code>_id</code> + <code>promoteId</code> for Identify↔table), geojson source/parse/worker (<code>configureGisWorker</code>, <code>resolveGisWorkerUrl</code>, <code>terminateGeojsonWorker</code>, …), <code>GEOJSON_STYLE_AUTO</code></td></tr><tr><td><code>./data-management</code></td><td><code>createDataManagement</code>, <code>createLocalStore</code>, <code>createHttpStore</code>, <code>createDataManager</code>, <code>toRecord</code> / <code>toFeature</code> / <code>toFeatureCollection</code>, <code>isDataManagementView</code></td></tr><tr><td><code>./raster</code></td><td><code>createRasterUrlDataset</code>, raster source part, <code>RASTER_XYZ_SAMPLES</code></td></tr><tr><td><code>./vector-tile</code></td><td><code>createVectorTileDataset</code> / <code>VectorTileDatasetOption</code>, <code>createDatasetPartVectorTileComponent</code>, <code>VECTOR_SAMPLES</code> / <code>VECTOR_TILE_SAMPLES</code> / <code>TILEJSON_SAMPLES</code>, local archive tile URLs <code>mbtilesLocalTilesUrl</code> / <code>pmtilesLocalTilesUrl</code> (<code>mbtiles-local://</code> / <code>pmtiles-local://</code> via <code>ensureVectorTileProtocols</code>), vector-tile worker (<code>configureVectorTileWorker</code>, <code>openMbtilesArchive</code> / <code>openPmtilesUrl</code> / <code>openPmtilesFile</code>, …)</td></tr><tr><td><code>./identify</code></td><td><code>IDENTIFY_*</code>, <code>createDatasetPartIdentify*</code>, <code>handleMultiIdentify*</code>, <code>runIdentifyMulti</code> / <code>runIdentifyShowFirst</code> (+ layer-filter / result-panel helpers), <code>createIdentifySession</code> / <code>createIdentifyControlModel</code> / scoped-session helpers, scope helpers, <code>resolveIdentifyHitAction</code> / <code>onSingle</code>·<code>onMultiple</code> builder, <code>createDefaultIdentifyResolver</code> / <code>setIdentifyResolver</code> / <code>getIdentifyResolver</code>, <code>createIdentifyFeatureResolver</code> / <code>resolveIdentifyFeatures</code> (getFeature → source → rendered → <code>Feature[]</code>), highlight session (<code>paintHighlight</code> / <code>paintHighlights</code> / <code>clearHighlight</code> / <code>onDetailClose</code> / <code>onIdentifyClose</code> / <code>paintIdentifyResultFocus</code> / <code>syncIdentifyPointerPick</code>), <code>createDefaultHighlightResolver</code> / <code>setHighlightResolver</code> / <code>getHighlightResolver</code> / <code>runHighlightFromRecords</code>; types <code>IIdentifyView*</code>, <code>IdentifyFeatureRow</code>, <code>IdentifyMultiResult</code>, <code>IdentifyHitAction</code>, <code>HighlightSessionIntent</code>, <code>HighlightContext</code> (canonical result row shape; former <code>IdentifySingleResult</code> / <code>IdentifyResult</code> aliases removed)</td></tr><tr><td><code>./menu</code></td><td><code>LIST_VIEW_MENU_*</code>, <code>createMenu*</code> (list-view / dataset builders), <code>createMapContextMenuBuilder</code>, <code>createLegend</code> / <code>createMultiLegend</code>, <code>handleMenuAction*</code>, <code>runFitBoundsMenuAction</code> / <code>resolveFitBoundsMenuTarget</code> (camera-only — never paints highlight), menu part builders; <code>MenuItem*</code> / <code>MenuAction</code> / <code>MenuItemProps</code> payload <code>P</code> defaults to <code>unknown</code> (types-only tightening vs former <code>any</code>)</td></tr><tr><td><code>./style</code></td><td><code>LayerSimpleMapboxBuild</code>, <code>LayerRasterMapboxBuild</code>, <code>*_CONFIG</code>, <code>TABS</code>, <code>CONFIG_TAB_BASE</code> / <code>buildConfigTabs</code>, <code>applyStyleTabValue</code> / <code>applyStyleZoom</code>, <code>STYLE_CONTROL_LOCALE</code></td></tr><tr><td><code>./create-control</code></td><td><code>CREATE_CONTROL_*</code>, <code>LAYER_TYPES</code> / <code>LayerHelper</code> / <code>Config*Helper</code> (incl. <code>ConfigTilejsonHelper</code>, <code>ConfigFilegdbHelper</code>) / <code>createLayerFormHelper</code> / <code>normalizeLayerType</code>, <code>assertCreateControlFileSize</code> / <code>formatCreateControlBytes</code> / <code>CREATE_CONTROL_MAX_FILE_BYTES</code>, <code>parseGis*</code> / <code>loadGis*</code> / upload helpers (<code>looksCompleteGis</code>, <code>parseCreateControlUploadedFiles</code>, <code>collectFilesFromDataTransfer</code>, <code>collectFileGdbFilesFromDataTransfer</code>, <code>readClipboardGisPaste</code>, <code>loadCreateControlTileJsonFromUrl</code> / <code>tileJsonToCreateControlPatch</code>, <code>summarizeFileGdbLayerMeta</code>, <code>createControlGeojsonPreviewPatch</code>, …), <code>configureFileGdbGdal</code> / <code>featuresWithGeometry</code>, <code>getCreateControlSamples</code> / <code>applyCreateControlSample</code> — GIS format peers (<code>shpjs</code>, <code>papaparse</code>, <code>@tmcw/togeojson</code>, <code>jszip</code>, <code>topojson-client</code>, <code>@xmldom/xmldom</code>, <code>gdal3.js</code>) and archive peers (<code>pmtiles</code>, <code>sql.js</code>) are <strong>optional</strong>; install when using CreateControl / file parse — <a href="./peers-and-bundle.html">peers-and-bundle</a>. CreateControl data kinds: <code>geojson</code> | <code>filegdb</code> | <code>xyz</code> | <code>tilejson</code> | <code>mbtiles</code> | <code>pmtiles</code> (legacy <code>vector</code> / <code>rasterxyz</code> / <code>vectortile</code> / <code>raster</code> normalize via <code>normalizeLayerType</code>; samples use <code>layerKind</code> only)</td></tr><tr><td><code>./geo-export</code></td><td><code>GEO_EXPORT_*</code> / <code>GEO_EXPORT_COMPONENT_KEY</code> (SoT; <code>LIST_VIEW_MENU_COMPONENT_KEY.exportGeo*</code> aliases), <code>createGeoExportController</code>, <code>onExport</code> + <code>GeoExportContext</code> (+ <code>AbortSignal</code>), <code>uiMode</code> modal|menu|click, <code>formComponent</code> / <code>loadingComponent</code>, <code>resolveGeoExportUiSlot</code>, <code>resolveExportCollection</code>, active-source bridge, <code>createMenuItemExportGeo</code>, <code>createDatasetPartGeoExport</code>, <code>openGeoExportModalFromAttributeTable</code> / <code>runGeoExportClickFromAttributeTable</code> / <code>runGeoExportFormatFromAttributeTable</code>, <code>resolveGeoExportCrs</code>, <code>downloadBlob</code> / <code>sanitizeExportFilename</code>, <code>getDatasetFeatureCollection</code> / <code>hasGeojsonExportData</code>, <code>ExportGeoComponentAttrs</code> (<code>exportHandler</code>)</td></tr><tr><td><code>./vite</code></td><td><code>mapDatasetGisWorker()</code> — Vite optimizeDeps + maplibre named-export shim for published package consumers</td></tr><tr><td><code>./geojson-worker</code></td><td>Static single-file GIS worker (<code>assets/geojson.worker.js</code>) for Webpack / CDN / static hosts</td></tr><tr><td><code>./style.css</code> / <code>./assets/*</code></td><td>package CSS and static assets</td></tr></tbody></table><p><code>LIST_VIEW_MENU_ID</code> / <code>LIST_VIEW_MENU_COMPONENT_KEY</code> <strong>string values</strong> remain SemVer-stable (import from <code>@hungpvq/map-dataset/menu</code>).</p><p>Map context menu ids, built-in item builders, and types (<code>MAP_CONTEXT_MENU_ID</code>, <code>createMapMenuBuilder</code>, <code>createDefaultMapContextMenuItems</code>, <code>MapContextMenuTarget</code>, …) import from <code>@hungpvq/map-core/menu</code> — not re-exported from <code>@hungpvq/map-dataset/menu</code>.</p><h2 id="hungpvq-vue-map-core-hungpvq-react-map-core" tabindex="-1"><code>@hungpvq/vue-map-core</code> / <code>@hungpvq/react-map-core</code> <a class="header-anchor" href="#hungpvq-vue-map-core-hungpvq-react-map-core" aria-label="Permalink to &quot;`@hungpvq/vue-map-core` / `@hungpvq/react-map-core`&quot;">​</a></h2><p>Root barrels are <strong>Stable only</strong> (see each <code>public-api.spec.ts</code>). Field / lightweight UI helpers live on <strong><code>./fields</code></strong> (Experimental; may change in a <strong>minor</strong>).</p><p><strong>Breaking (major):</strong> importing former Experimental symbols (<code>Input*</code>, <code>MapCard</code>, <code>MapErrorToast</code>, …) from the package root fails — use <code>@hungpvq/vue-map-core/fields</code> / <code>@hungpvq/react-map-core/fields</code>. Former <code>BaseButton</code> is removed — use Stable root <code>MapControlButton</code>.</p><p>Shared root highlights:</p><table tabindex="0"><thead><tr><th>Area</th><th>Stable surface</th></tr></thead><tbody><tr><td>Shell</td><td><code>Map</code> container; dual events <strong><code>mapLoaded</code> / <code>mapDestroy</code> / <code>error</code></strong> — Vue <code>@mapLoaded</code> / <code>@mapDestroy</code> / <code>@error</code>, React <code>onMapLoaded</code> / <code>onMapDestroy</code> / <code>onError</code>; optional <code>keyboardShortcuts</code> (default true); mounts <code>MapErrorToast</code> internally from <code>./fields</code>. Shell MapLibre defaults from <code>MapInitializer.createDefaultOptions</code> (<code>attributionControl: false</code>, …)</td></tr><tr><td>Hooks</td><td><code>useMap</code>, <code>useMapInstance</code>, <code>useShow</code>, <code>useRegisterMapControl</code>, <code>useUniversalRegistry</code></td></tr><tr><td>Store helpers</td><td><code>createMapScopedStore</code>, <code>destroyMapScopedStore</code>, <code>getStore</code>, <code>addStore</code>, <code>isUsableMapId</code> (not <code>getMap</code>) — <a href="./map-store.html">map-store</a></td></tr><tr><td>Registry</td><td>Framework <code>UniversalRegistry</code>, <code>RegistryItem</code></td></tr><tr><td>Controls</td><td>ModuleContainer controls + <strong>control ids</strong> / action types (<a href="./registry-controls.html">registry-controls</a>); both export <code>ActionControl</code>; action UI uses <code>MapControlButton</code> (<code>variant</code>: <code>icon</code> | <code>plain</code> | <code>text</code> | <code>tonal</code> | <code>outlined</code> | <code>filled</code>; <code>size</code>: <code>small</code> | <code>medium</code> | <code>large</code> | number px — see <a href="./css-variables.html#core---mapcontrolbutton--mapbutton">css-variables</a>) / <code>MapCommonButton</code> / <strong><code>MapCopyButton</code></strong> (clipboard + icon feedback; see <a href="./css-variables.html#core---mapcopybutton">css-variables</a>)</td></tr><tr><td>Types</td><td>First-party: <code>WithShowProps</code>; prefer <code>WithMapPropType</code> / <code>MapSimple</code> from <code>@hungpvq/map-core</code></td></tr></tbody></table><p>Framework idioms (Stable, <strong>not</strong> dual-export parity): Vue <code>makeShowProps</code> / <code>withMapProps</code>; React <code>MapContext</code> / <code>MapContextProvider</code> / <code>useMapContext</code> / <code>ReactMapStoreAdapter</code> / <code>MapControlButtonGroupContext</code>. Do not expect these on the other adapter. React also exports imperative <code>getMapMittStore</code> (same as <code>useMapMittStore</code>) for non-hook call sites — rules-of-hooks. Root bag: <code>getMapCoreRootStore</code> / <code>MAP_CORE_ROOT_STORE_KEY</code> on <code>@hungpvq/map-core</code>.</p><p>Package entries: <code>.</code> + <code>./style.css</code> + <strong><code>./fields</code></strong>.</p><h3 id="hungpvq-vue-map-core-fields-hungpvq-react-map-core-fields" tabindex="-1"><code>@hungpvq/vue-map-core/fields</code> / <code>@hungpvq/react-map-core/fields</code> <a class="header-anchor" href="#hungpvq-vue-map-core-fields-hungpvq-react-map-core-fields" aria-label="Permalink to &quot;`@hungpvq/vue-map-core/fields` / `@hungpvq/react-map-core/fields`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Symbol</th><th>Notes</th></tr></thead><tbody><tr><td><code>BaseCollapse</code>, <code>Collapse</code></td><td>Collapse panel — <strong>canonical <code>BaseCollapse</code></strong>; <code>Collapse</code> alias</td></tr><tr><td><code>InputCheckbox</code>, <code>InputChoose</code>, <code>InputColorPicker</code>, <code>InputCrs</code>, <code>InputFile</code>, <code>InputSelect</code>, <code>InputSlider</code>, <code>InputText</code>, <code>InputTextArea</code>, <code>InputTextarea</code></td><td>Form helpers — <strong>canonical <code>InputTextArea</code></strong>; <code>InputTextarea</code> alias</td></tr><tr><td><code>MapButton</code></td><td>Map-control chrome (<code>variant</code> / <code>size</code> same as <code>MapControlButton</code>; prefer Stable root <code>MapControlButton</code> in apps)</td></tr><tr><td><code>MapCard</code>, <code>MapIcon</code>, <code>MapImage</code></td><td>Lightweight map UI primitives</td></tr><tr><td><code>MapErrorToast</code></td><td>Listens to <code>errorHandler</code>; “Open errors” dispatches <code>hungpvq:map-open-devtools-errors</code></td></tr><tr><td><code>DragDropFile</code></td><td>Vue + React <code>/fields</code> (DOM-only drop zone)</td></tr></tbody></table><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { MapControlButton, MapCopyButton } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;@hungpvq/vue-map-core&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { InputText } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;@hungpvq/vue-map-core/fields&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// or `@hungpvq/react-map-core` / `.../fields`</span></span></code></pre></div><p><code>MapControlButton</code>: <code>variant</code> + <code>size</code> (<code>small</code> | <code>medium</code> | <code>large</code> | px). Prefer <code>size=&quot;small&quot;</code> in dense layer rows; default <code>medium</code> matches draggable header chrome (32px).</p><p><code>MapCopyButton</code>: Stable root copy action — wraps <code>MapControlButton</code> + core <code>createCopyFeedback</code>. On success, icon <code>mdiContentCopy</code> → <code>mdiCheck</code> and title → <code>copiedTitle</code> for ~1.5s (<code>COPY_FEEDBACK_MS</code>). <strong>No toast.</strong> Prefer this for every text-copy chrome button (InfoControl rows, LayerDetail cells, measurement CRS values, …).</p><p>Prefer canonical names in new code (<code>MapControlButton</code>, <code>MapCopyButton</code>, <code>BaseCollapse</code>, <code>InputTextArea</code>). Authoritative lock: root Stable + <code>*_FIELDS_RUNTIME_EXPORTS</code> in each adapter <code>public-api.spec.ts</code>.</p><p><strong>Parity lock:</strong> <code>libs/map-core/core/src/dual/parity-catalog.ts</code> + <code>vue-react-parity.spec.ts</code> (shared control ids + shared Stable root + shared <code>/fields</code> Experimental names).</p><p>Dataset / draw Experimental allowlists are <strong>empty / reserved</strong>. <code>@hungpvq/map-core</code> Experimental root: <code>GeoLocateSession</code> (Mapbox-style geolocate engine used by Vue/React <code>GeoLocateControl</code>; may change in a <strong>minor</strong>); <code>DEVTOOLS_CONTROL</code> (shared Map-scoped Devtools control id; may change in a <strong>minor</strong>). <code>@hungpvq/map-core/devtools</code> also exports Experimental <code>formatDevtoolsLogEntryForCopy</code> for LogViewer clipboard formatting.</p><p>Adapters do <strong>not</strong> re-export <code>@hungpvq/map-core</code> protocol (<code>getMap</code>, <code>errorHandler</code>, …). There is no adapter <code>handleError</code> — apps use <code>errorHandler</code> from <code>@hungpvq/map-core</code>.</p><h2 id="hungpvq-vue-map-dataset-hungpvq-react-map-dataset" tabindex="-1"><code>@hungpvq/vue-map-dataset</code> / <code>@hungpvq/react-map-dataset</code> <a class="header-anchor" href="#hungpvq-vue-map-dataset-hungpvq-react-map-dataset" aria-label="Permalink to &quot;`@hungpvq/vue-map-dataset` / `@hungpvq/react-map-dataset`&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Area</th><th>Stable surface</th></tr></thead><tbody><tr><td>Bootstrap</td><td><code>installMapApp</code>, <code>createMapAppPlugin</code> (Vue), <code>createDatasetRegistryPlugin()</code></td></tr><tr><td>Hooks</td><td><code>useMapDataset</code> (incl. <code>datasetVersion</code>), <code>useMapHighlight</code></td></tr><tr><td>UI</td><td><code>LayerControl</code>, <code>IdentifyControl</code>, <code>IdentifyResultControl</code>, <code>IdentifyShowFirstControl</code>, <code>AttributeTable</code> (+ <code>AttributeTableView</code> / toolbar / grid / pager), <code>StyleControl</code>, <code>CreateControl</code>, <code>ComponentManagementControl</code>, <code>DatasetDetail</code>, <code>LayerMenuDefaultHandle</code>, …</td></tr><tr><td>Core boundary</td><td>Builders/services/types from <code>@hungpvq/map-dataset</code> (including <code>createLegend</code> / <code>createMultiLegend</code> from <code>@hungpvq/map-dataset/menu</code>)</td></tr></tbody></table><p>Menu condition: Vue <code>provideMenuConditionContext</code> / <code>MENU_CONDITION_CONTEXT_KEY</code>; React <code>MenuConditionProvider</code>. Imperative bag access: <code>getMapDatasetStore</code> / <code>notifyMapDatasetStore</code> (adapters + <code>@hungpvq/map-dataset</code>). UI list refresh: depend on <code>useMapDataset().datasetVersion</code> — see <a href="/docs/map/dataset/helper/useMapDataset.html">useMapDataset</a>.</p><h2 id="hungpvq-map-draw" tabindex="-1"><code>@hungpvq/map-draw</code> <a class="header-anchor" href="#hungpvq-map-draw" aria-label="Permalink to &quot;`@hungpvq/map-draw`&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Area</th><th>Stable surface</th></tr></thead><tbody><tr><td>Service</td><td><code>DrawService</code></td></tr><tr><td>Protocol</td><td><code>DrawingType</code>, <code>DrawingTypeName</code>, <code>MAP_DRAW_EVENT</code>, <code>MAP_DRAW_STORE_KEY</code>, <code>MapDrawOption</code>, <code>MapDrawEndPayload</code> <code>{ mapId }</code>, <code>isDraftOption</code>, <code>ensureMapDrawStore</code> / <code>createDefaultMapDrawStore</code></td></tr><tr><td>Engine mount</td><td><code>MapDraw</code>, <code>StaticMode</code>, <code>DRAW_MODES</code>, <code>getDrawStyles</code></td></tr><tr><td>Styles / query / ids</td><td><code>getFeatureByMap</code>, <code>getFirstFeatureByMap</code>, <code>getFeatureId</code>, <code>sameFeature</code></td></tr><tr><td>Locales</td><td><code>DRAW_CONTROL_LOCALE</code>, <code>INSPECT_CONTROL_LOCALE</code></td></tr><tr><td>Experimental (<code>@hungpvq/map-draw</code>)</td><td><code>createDrawSession</code> (<code>prepareSave</code> / <code>finishCancel</code> / <code>redrawNonDraft</code>, …), <code>draw-control-helpers</code> (<code>handleDrawMapClick</code>, …), <code>logger</code></td></tr></tbody></table><p>Inspect helpers (<code>brightColor</code>, <code>generateInspectStyle</code>, …) remain public; inventory tagged <code>in-use-first-party</code> via InspectControl.</p><h2 id="hungpvq-vue-map-draw-hungpvq-react-map-draw" tabindex="-1"><code>@hungpvq/vue-map-draw</code> / <code>@hungpvq/react-map-draw</code> <a class="header-anchor" href="#hungpvq-vue-map-draw-hungpvq-react-map-draw" aria-label="Permalink to &quot;`@hungpvq/vue-map-draw` / `@hungpvq/react-map-draw`&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Area</th><th>Stable surface</th></tr></thead><tbody><tr><td>Shell</td><td><code>DrawControl</code>, <code>InspectControl</code> (shared <code>InspectController</code>), <code>useMapDraw</code>, <code>useConfigDrawControl</code>, <code>useMapDrawStore</code></td></tr><tr><td>Control ids</td><td><code>mapDrawDraftList</code>, <code>mapInspectControl</code></td></tr><tr><td>Core boundary</td><td>Protocol / <code>isDraftOption</code> / locales from <code>@hungpvq/map-draw</code> — adapters do <strong>not</strong> re-export them</td></tr></tbody></table><p>Consumer docs: <code>libs/map-core/map-draw/docs</code> → <code>/map/draw/</code>.</p><h2 id="hungpvq-vue-map-devtools-hungpvq-react-map-devtools" tabindex="-1"><code>@hungpvq/vue-map-devtools</code> / <code>@hungpvq/react-map-devtools</code> <a class="header-anchor" href="#hungpvq-vue-map-devtools-hungpvq-react-map-devtools" aria-label="Permalink to &quot;`@hungpvq/vue-map-devtools` / `@hungpvq/react-map-devtools`&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Area</th><th>Stable surface</th></tr></thead><tbody><tr><td>Bootstrap (both)</td><td><code>installDevtools</code> / <code>uninstallDevtools</code> (<code>installDevtools({ logStore })</code>: <code>&#39;indexeddb&#39;</code> | <code>&#39;memory&#39;</code> | options | custom <code>LogDataStore</code>)</td></tr><tr><td>Panel</td><td><code>Devtools</code> (mount <strong>inside</strong> <code>&lt;Map&gt;</code>; <code>DraggableItemPopup</code>)</td></tr><tr><td>Map control</td><td><code>DevtoolsControl</code> / <code>DEVTOOLS_CONTROL.id</code> (<code>mapDevtools</code>) — same popup path</td></tr><tr><td>Open helpers</td><td><code>openMapDevtoolsErrors</code>, <code>setDevtoolOpen</code>, <code>toggleDevtoolOpen</code>, …</td></tr><tr><td>Store helpers (both)</td><td><code>DevtoolLogAdapter</code>, <code>devtoolLogAdapter</code>, <code>devtoolState</code>, <code>getDevtoolState</code>, <code>useDevtoolState</code>, <code>subscribeDevtoolState</code>, <code>toggleDevtoolOpen</code>, <code>setDevtoolActiveTab</code>, <code>clearDevtoolLogs</code>, <code>clearDevtoolErrors</code></td></tr><tr><td>Docs</td><td><a href="./devtools.html">devtools.md</a></td></tr></tbody></table><p><code>openMapDevtoolsErrors</code> opens the panel on the Errors tab. <code>MapErrorToast</code> (from <code>@hungpvq/*-map-core/fields</code>) dispatches <code>hungpvq:map-open-devtools-errors</code>; stores listen and call <code>openMapDevtoolsErrors</code>.</p><p>Adapters do <strong>not</strong> re-export <code>@hungpvq/map-core</code> (<code>errorHandler</code> from map-core). See <a href="./error-handling.html">Error handling</a>.</p><h2 id="css" tabindex="-1">CSS <a class="header-anchor" href="#css" aria-label="Permalink to &quot;CSS&quot;">​</a></h2><p>Documented <code>--map-*</code> tokens and theme classes (<code>map-theme-*</code>) in <a href="./css-variables.html">CSS variables</a>. <code>style.css</code> package entries are stable import paths.</p><h2 id="experimental-slot" tabindex="-1">Experimental slot <a class="header-anchor" href="#experimental-slot" aria-label="Permalink to &quot;Experimental slot&quot;">​</a></h2><p>Vue/React <code>@hungpvq/*-map-core</code> publish field/UI helpers on <strong><code>./fields</code></strong> (not the root barrel) — see <a href="#hungpvqvue-map-core--hungpvqreact-map-core">vue/react map-core</a>. They may change in a <strong>minor</strong>. Root <code>*_EXPERIMENTAL_RUNTIME_EXPORTS</code> for adapters are empty/reserved. Removing an Experimental export from a published barrel (including <code>./fields</code>) remains a <strong>major</strong>. <code>@hungpvq/map-core</code> Experimental: <code>GeoLocateSession</code>, <code>DEVTOOLS_CONTROL</code>. Other map packages keep empty/reserved experimental lists.</p><h2 id="enforcing-the-allowlist" tabindex="-1">Enforcing the allowlist <a class="header-anchor" href="#enforcing-the-allowlist" aria-label="Permalink to &quot;Enforcing the allowlist&quot;">​</a></h2><ol><li>Edit <code>src/index.ts</code> with <strong>named</strong> exports only (no public <code>export *</code>). Prefer <code>export { X } from &#39;./feature/leaf&#39;</code>. Export first-party types with explicit <code>export type { … }</code> — never <code>export type *</code>, and never re-export third-party library types.</li><li>Put new implementation symbols in feature modules; only promote to root <code>index.ts</code> + allowlist when intentional.</li><li>Update the matching <code>public-api.spec.ts</code> allowlist arrays (runtime symbols only).</li><li>Update this page when changing Stable.</li><li>Do not hand-edit package <code>CHANGELOG.md</code> unless asked — use release tooling.</li></ol>',73)]))}const m=o(r,[["render",a]]);export{u as __pageData,m as default};
